"""Core data types. Every datetime here is timezone-aware."""

from dataclasses import dataclass
from datetime import UTC, date, datetime, time, timedelta
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

MAX_NIGHT_LENGTH = timedelta(hours=16)


def zone(name: str) -> ZoneInfo:
    """Look up an IANA time zone, e.g. 'America/Toronto'. Raises ValueError if unknown."""
    try:
        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError) as error:
        raise ValueError(f"Unknown time zone: {name!r}") from error


@dataclass(frozen=True)
class Night:
    """One night in the sleep diary."""

    bedtime: datetime
    wake_time: datetime
    timezone: str  # the user's IANA time zone that night
    notes: str = ""  # free-text journal; this is user data, never instructions
    id: int | None = None

    def __post_init__(self) -> None:
        for name in ("bedtime", "wake_time"):
            if getattr(self, name).tzinfo is None:
                raise ValueError(f"{name} must be timezone-aware")
        zone(self.timezone)
        if self.wake_time <= self.bedtime:
            raise ValueError("wake time must be after bedtime")
        if self.duration > MAX_NIGHT_LENGTH:
            raise ValueError("a night can't be longer than 16 hours")

    @property
    def local_bedtime(self) -> datetime:
        return self.bedtime.astimezone(zone(self.timezone))

    @property
    def night_of(self) -> date:
        """The evening this night began: a 00:15 bedtime on Sunday is Saturday night."""
        return (self.local_bedtime - timedelta(hours=12)).date()

    @property
    def local_wake_time(self) -> datetime:
        return self.wake_time.astimezone(zone(self.timezone))

    @property
    def duration(self) -> timedelta:
        # Subtract in UTC: same-zone subtraction uses wall clocks and is wrong across DST.
        return self.wake_time.astimezone(UTC) - self.bedtime.astimezone(UTC)


@dataclass(frozen=True)
class User:
    """The (single) NightJar user and their current settings."""

    name: str
    timezone: str  # where the user is now
    quiet_start: time | None = None  # Do Not Disturb, e.g. 23:00
    quiet_end: time | None = None  # e.g. 07:00
"""Sleep diary storage (SQLite) and CSV import.

Datetimes are stored in UTC (ISO 8601) so they sort correctly; each night keeps
the IANA time zone the user was in, so local times can always be rebuilt.
"""

import csv
import io
import sqlite3
from collections.abc import Iterator
from contextlib import contextmanager
from datetime import UTC, datetime, time
from pathlib import Path

from nightjar.models import Night, User, zone

DEFAULT_USER = User(
    name="Sam", timezone="America/Toronto", quiet_start=time(23, 0), quiet_end=time(7, 0)
)
CSV_COLUMNS = {"bedtime", "wake_time", "timezone", "notes"}

SCHEMA = """
CREATE TABLE IF NOT EXISTS nights (
    id INTEGER PRIMARY KEY,
    bedtime_utc TEXT NOT NULL,
    wake_time_utc TEXT NOT NULL,
    timezone TEXT NOT NULL,
    notes TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS user_settings (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    name TEXT NOT NULL,
    timezone TEXT NOT NULL,
    quiet_start TEXT,
    quiet_end TEXT
);
"""


class Diary:
    """All reads and writes for one user's diary."""

    def __init__(self, path: str | Path) -> None:
        self.path = str(path)
        with self._connect() as db:
            db.executescript(SCHEMA)

    @contextmanager
    def _connect(self) -> Iterator[sqlite3.Connection]:
        db = sqlite3.connect(self.path)
        try:
            with db:  # commits on success, rolls back on error
                yield db
        finally:
            db.close()

    def add_night(self, night: Night) -> None:
        with self._connect() as db:
            db.execute(
                "INSERT INTO nights (bedtime_utc, wake_time_utc, timezone, notes)"
                " VALUES (?, ?, ?, ?)",
                (
                    _to_utc_text(night.bedtime),
                    _to_utc_text(night.wake_time),
                    night.timezone,
                    night.notes,
                ),
            )

    def add_nights(self, nights: list[Night]) -> int:
        for night in nights:
            self.add_night(night)
        return len(nights)

    def nights(self) -> list[Night]:
        """All nights, newest first."""
        with self._connect() as db:
            rows = db.execute(
                "SELECT id, bedtime_utc, wake_time_utc, timezone, notes"
                " FROM nights ORDER BY bedtime_utc DESC"
            ).fetchall()
        return [
            Night(
                id=row[0],
                bedtime=datetime.fromisoformat(row[1]),
                wake_time=datetime.fromisoformat(row[2]),
                timezone=row[3],
                notes=row[4],
            )
            for row in rows
        ]

    def user(self) -> User:
        with self._connect() as db:
            row = db.execute(
                "SELECT name, timezone, quiet_start, quiet_end FROM user_settings"
            ).fetchone()
        if row is None:
            return DEFAULT_USER
        return User(
            name=row[0],
            timezone=row[1],
            quiet_start=_parse_time(row[2]),
            quiet_end=_parse_time(row[3]),
        )

    def save_user(self, user: User) -> None:
        zone(user.timezone)  # validate before saving
        with self._connect() as db:
            db.execute(
                "INSERT OR REPLACE INTO user_settings VALUES (1, ?, ?, ?, ?)",
                (
                    user.name,
                    user.timezone,
                    _format_time(user.quiet_start),
                    _format_time(user.quiet_end),
                ),
            )


def parse_csv(text: str) -> list[Night]:
    """Parse diary CSV: bedtime,wake_time,timezone,notes (ISO 8601 with UTC offsets)."""
    reader = csv.DictReader(io.StringIO(text))
    missing = CSV_COLUMNS - set(reader.fieldnames or [])
    if missing:
        raise ValueError(f"CSV is missing columns: {', '.join(sorted(missing))}")
    nights = []
    for line_number, row in enumerate(reader, start=2):
        try:
            nights.append(
                Night(
                    bedtime=parse_aware(row["bedtime"]),
                    wake_time=parse_aware(row["wake_time"]),
                    timezone=row["timezone"].strip(),
                    notes=(row["notes"] or "").strip(),
                )
            )
        except ValueError as error:
            raise ValueError(f"Line {line_number}: {error}") from error
    return nights


def parse_aware(text: str) -> datetime:
    """Parse an ISO 8601 datetime that must include a UTC offset."""
    value = datetime.fromisoformat(text.strip())
    if value.tzinfo is None:
        raise ValueError(f"{text!r} has no UTC offset")
    return value


def local_input_to_aware(text: str, timezone: str) -> datetime:
    """Turn an HTML datetime-local value ('2026-03-19T23:00') into an aware datetime."""
    return datetime.fromisoformat(text).replace(tzinfo=zone(timezone))


def _to_utc_text(value: datetime) -> str:
    return value.astimezone(UTC).isoformat()


def _parse_time(text: str | None) -> time | None:
    return time.fromisoformat(text) if text else None


def _format_time(value: time | None) -> str | None:
    return value.strftime("%H:%M") if value else None
"""Story S-114: a gentle wind-down nudge before the user's usual bedtime."""

from dataclasses import dataclass
from datetime import UTC, date, datetime, time, timedelta
from zoneinfo import ZoneInfo

from nightjar.claims import load_register
from nightjar.models import Night, User, zone
from nightjar.sleep_window import usual_bedtime

WIND_DOWN_LEAD = timedelta(minutes=45)


@dataclass(frozen=True)
class Nudge:
    at: datetime  # aware, in the user's current time zone
    silent: bool  # True during quiet hours: deliver without sound, don't skip
    text: str


def next_nudge(user: User, nights: list[Night], now: datetime) -> Nudge | None:
    """The next wind-down nudge after `now`, or None on a cold start (< 7 nights)."""
    if now.tzinfo is None:
        raise ValueError("now must be timezone-aware")
    bedtime = usual_bedtime(nights)
    if bedtime is None:
        return None

    user_zone = zone(user.timezone)  # the user's *current* zone (AC2)
    nudge_time = clock_minus(bedtime, WIND_DOWN_LEAD)
    today = now.astimezone(user_zone).date()
    at = at_local_time(today, nudge_time, user_zone)
    if at.astimezone(UTC) <= now.astimezone(UTC):  # compare instants, not wall clocks
        at = at_local_time(today + timedelta(days=1), nudge_time, user_zone)

    return Nudge(
        at=at,
        silent=in_quiet_hours(user, at.time()),  # delivered wall time, not the nominal one
        text=nudge_text(bedtime, at.date()),
    )


def at_local_time(day: date, clock_time: time, user_zone: ZoneInfo) -> datetime:
    """`clock_time` on `day` in `user_zone`.

    The UTC round trip normalises wall times that DST skips (02:30 on
    spring-forward day becomes 03:30) so the result is a real instant.
    """
    wall_clock = datetime.combine(day, clock_time, tzinfo=user_zone)
    return wall_clock.astimezone(UTC).astimezone(user_zone)


def clock_minus(clock_time: time, delta: timedelta) -> time:
    """Time-of-day arithmetic that wraps around midnight (00:10 - 45 min = 23:25)."""
    start = datetime.combine(date(2000, 1, 2), clock_time, tzinfo=UTC)
    return (start - delta).time()


def in_quiet_hours(user: User, clock_time: time) -> bool:
    start, end = user.quiet_start, user.quiet_end
    if start is None or end is None:
        return False
    if start <= end:
        return start <= clock_time < end
    return clock_time >= start or clock_time < end  # window wraps midnight


def nudge_text(bedtime: time, day: date) -> str:
    """Pick approved copy from the claims register (AC4); it varies by day."""
    templates = load_register()["nudge_copy"]
    template = templates[day.toordinal() % len(templates)]
    return template.format(bedtime=bedtime.strftime("%H:%M"))
"""The NightJar web app: one server-rendered page plus a small JSON API.

Run with:  uv run uvicorn nightjar.web:create_app --factory --reload
"""

import os
from collections.abc import Callable
from datetime import UTC, datetime, time
from pathlib import Path

from fastapi import FastAPI, Form, Request, UploadFile
from fastapi.responses import HTMLResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles
from fastapi.templating import Jinja2Templates
from pydantic import BaseModel

from nightjar.coach import Coach, ask_coach, get_coach
from nightjar.coach.service import DEFAULT_TRACE_PATH
from nightjar.diary import Diary, local_input_to_aware, parse_csv
from nightjar.models import Night, User
from nightjar.nudge import next_nudge
from nightjar.sleep_window import usual_bedtime

HERE = Path(__file__).parent
Clock = Callable[[], datetime]


def system_clock() -> datetime:
    return datetime.now(UTC)


class CoachQuestion(BaseModel):
    question: str


def create_app(
    diary: Diary | None = None,
    coach: Coach | None = None,
    clock: Clock = system_clock,
    trace_path: Path = DEFAULT_TRACE_PATH,
) -> FastAPI:
    diary = diary or Diary(os.environ.get("NIGHTJAR_DB", "nightjar.db"))
    coach = coach or get_coach()
    templates = Jinja2Templates(directory=HERE / "templates")
    app = FastAPI(title="NightJar")
    app.mount("/static", StaticFiles(directory=HERE / "static"), name="static")

    def render(request: Request, status_code: int = 200, **extra) -> HTMLResponse:
        user, nights = diary.user(), diary.nights()
        context = {
            "user": user,
            "nights": nights,
            "usual_bedtime": usual_bedtime(nights),
            "nudge": next_nudge(user, nights, clock()),
            "imported": request.query_params.get("imported"),
            **extra,
        }
        return templates.TemplateResponse(request, "index.html", context, status_code=status_code)

    @app.get("/", response_class=HTMLResponse)
    def home(request: Request):
        return render(request)

    @app.post("/nights")
    def add_night(
        request: Request,
        bedtime: str = Form(...),
        wake_time: str = Form(...),
        timezone: str = Form(...),
        notes: str = Form(""),
    ):
        try:
            diary.add_night(
                Night(
                    bedtime=local_input_to_aware(bedtime, timezone),
                    wake_time=local_input_to_aware(wake_time, timezone),
                    timezone=timezone,
                    notes=notes.strip(),
                )
            )
        except ValueError as error:
            return render(request, status_code=400, error=str(error))
        return RedirectResponse("/", status_code=303)

    @app.post("/import")
    async def import_csv(request: Request, file: UploadFile):
        try:
            nights = parse_csv((await file.read()).decode("utf-8-sig"))
        except (ValueError, UnicodeDecodeError) as error:
            return render(request, status_code=400, error=f"Import failed. {error}")
        count = diary.add_nights(nights)
        return RedirectResponse(f"/?imported={count}", status_code=303)

    @app.post("/settings")
    def save_settings(
        request: Request,
        timezone: str = Form(...),
        quiet_start: str = Form(""),
        quiet_end: str = Form(""),
    ):
        try:
            diary.save_user(
                User(
                    name=diary.user().name,
                    timezone=timezone.strip(),
                    quiet_start=time.fromisoformat(quiet_start) if quiet_start else None,
                    quiet_end=time.fromisoformat(quiet_end) if quiet_end else None,
                )
            )
        except ValueError as error:
            return render(request, status_code=400, error=str(error))
        return RedirectResponse("/", status_code=303)

    @app.post("/coach", response_class=HTMLResponse)
    def coach_page(request: Request, question: str = Form(...)):
        answer = ask_coach(coach, diary.nights(), question, trace_path)
        return render(request, question=question, answer=answer)

    @app.get("/api/nudge")
    def api_nudge():
        nudge = next_nudge(diary.user(), diary.nights(), clock())
        if nudge is None:
            return {"nudge": None, "reason": "Log at least 7 nights to get a nudge."}
        return {
            "nudge": {
                "at": nudge.at.isoformat(),
                "local_time": f"{nudge.at:%H:%M}",
                "silent": nudge.silent,
                "text": nudge.text,
            }
        }

    @app.post("/api/coach")
    def api_coach(body: CoachQuestion):
        answer = ask_coach(coach, diary.nights(), body.question, trace_path)
        return {"answer": answer.text, "used_fallback": answer.used_fallback}

    return app
